UPDATE	AI_PROCESSING_QUEUE
SET 	STATUS  = 'RUNNING',
		RUN_AT  = NOW()
WHERE	MSGID= #{msgId}
AND     TASK_TYPE = #{taskType}

UPDATE	AI_PROCESSING_QUEUE
SET		STATUS='DONE',
		ERROR_MESSAGE=NULL
WHERE	MSGID= #{msgId}
AND     TASK_TYPE = #{taskType}

DELETE
FROM 	AI_PROCESSING_QUEUE
WHERE 	MSGID = #{msgId}
AND     TASK_TYPE = #{taskType}

UPDATE  AI_PROCESSING_QUEUE
SET		STATUS = 'FAILED',
		ERROR_MESSAGE = #{err}
WHERE 	MSGID = #{msgId}
AND     TASK_TYPE = #{taskType}
